// The rows: {words}, count, text, setup, expected
struct Arm64SemanticRow {
    uint32 m_words[4];
    uint m_count;
    const char* m_text;
    const char* m_setup;
    const char* m_expected;
};

#include "arm/Arm64SemanticRows.inc"

static const Arm64SemanticRow gArm64SemanticRows[] = {
    ARM64_SEMANTIC_ROWS
    { {0}, 0, NULL, NULL, NULL }
};

// Report a failure and count it
#define ARM_SEMANTIC_FAIL(row, message) \
    do { \
        fprintf(stderr, "TestArm64Semantics: %s [%s]: %s\n", (row), \
                __FILE__, (message)); \
        m_failures++; \
    } while (0)

// The memory of the tests: [0, 0x20000), zero unless set; the writes are kept
class TestArmRunMemory : public SemanticMemory {
public:
    virtual bool read(uint64 address, uint8* buffer, uint size)
    {
        if (!isValid(address, size))
            return false;
        for (uint i = 0; i < size; i++)
            buffer[i] = getByte(address + i);
        return true;
    }

    virtual bool write(uint64 address, const uint8* buffer, uint size)
    {
        if (!isValid(address, size))
            return false;
        for (uint i = 0; i < size; i++)
            set(address + i, buffer[i], true);
        return true;
    }

    uint8 getByte(uint64 address) const
    {
        return m_bytes.hasKey(address) ? m_bytes[address] : 0;
    }

    void set(uint64 address, uint8 value, bool isWritten)
    {
        if (m_bytes.hasKey(address))
            m_bytes[address] = value;
        else
            m_bytes.append(address, value);
        if (isWritten && !m_written.hasKey(address))
            m_written.append(address, true);
    }

    bool isWritten(uint64 address) const
    {
        return m_written.hasKey(address);
    }

    cList<uint64> getWritten() const
    {
        return m_written.keys();
    }

private:
    static bool isValid(uint64 address, uint size)
    {
        return (address < 0x20000) && (address + size <= 0x20000);
    }

    cHash<uint64, uint8> m_bytes;
    cHash<uint64, bool> m_written;
};

// A bad row of the tables is a failure of the test
#define ARM_ASSERT_TOKEN(condition) \
    do { if (!(condition)) { fprintf(stderr, "bad row token\n"); TESTS_ASSERT(false); } } while (0)

// Return a pointer to the instruction which doesn't own it
static OpcodePtr asOpcode(const ArmOpcodePtr& opcode)
{
    return OpcodePtr((Opcode*)opcode.getPointer(), SMARTPTR_DESTRUCT_NONE);
}

class TestObjectTestArm64Semantics : public cTestObject {
public:
    TestObjectTestArm64Semantics() : m_failures(0) {}

    // Parse a hexadecimal number of up to 128 bits
    static SemanticValue parseHex(const char* text, const char* end)
    {
        SemanticValue value;
        uint digits = (uint)(end - text);
        for (uint i = 0; i < digits; i++)
        {
            const char c = text[digits - 1 - i];
            uint nibble = (c >= 'a') ? (uint)(c - 'a' + 10) : (uint)(c - '0');
            value.setBits(i * 4, 4, nibble);
        }
        return value;
    }

    // The tokens "name=value" of a state string
    struct Token {
        cString m_name;
        const char* m_value;
        const char* m_end;
    };

    static uint split(const char* text, Token* tokens, uint maximum)
    {
        uint count = 0;
        const char* p = text;
        while ((*p != 0) && (count < maximum))
        {
            while (*p == ' ')
                p++;
            if (*p == 0)
                break;
            const char* end = p;
            while ((*end != 0) && (*end != ' '))
                end++;
            const char* equals = (const char*)memchr(p, '=', (size_t)(end - p));
            ARM_ASSERT_TOKEN(equals != NULL);
            tokens[count].m_name = cString(cString(p).left((uint)(equals - p)));
            tokens[count].m_value = equals + 1;
            tokens[count].m_end = end;
            count++;
            p = end;
        }
        return count;
    }

    // Parse "addr:hex,addr:hex" into the memory
    static void parseMemory(const char* text, const char* end, TestArmRunMemory& memory,
                            cHash<uint64, uint8>* expected)
    {
        const char* p = text;
        while (p < end)
        {
            const char* colon = (const char*)memchr(p, ':', (size_t)(end - p));
            ARM_ASSERT_TOKEN(colon != NULL);
            uint64 address = parseHex(p, colon).getWord(0);
            const char* q = colon + 1;
            uint count = 0;
            while ((q < end) && (*q != ','))
            {
                uint8 byte = (uint8)parseHex(q, q + 2).getWord(0);
                if (expected != NULL)
                {
                    if (expected->hasKey(address + count))
                        (*expected)[address + count] = byte;
                    else
                        expected->append(address + count, byte);
                } else
                {
                    memory.set(address + count, byte, false);
                }
                q += 2;
                count++;
            }
            p = (q < end) ? q + 1 : q;
        }
    }

    // Run a row. The row is OK if the state after the instructions is the
    // expected one: the registers which the row names have the value, all the
    // others are unchanged
    void runRow(const Arm64SemanticRow& row)
    {
        ArchitectureDescriptionPtr architecture(new Arm64Architecture(128, 512));
        ArmSemanticLifter lifter(OpcodeSubsystems::DISASSEMBLER_ARM_64_LE,
                                 architecture);
        TestArmRunMemory memory;
        SemanticInterpreter interpreter(architecture, memory);

        // The start state
        Token tokens[64];
        uint64 initialX[31];
        SemanticValue initialV[32];
        uint64 initialSp = 0x8000;
        uint64 pc = 0x1000;
        uint initialNzcv = 0;
        uint64 initialFpcr = 0, initialFpsr = 0;
        memset(initialX, 0, sizeof(initialX));
        const uint setupCount = split(row.m_setup, tokens, 64);
        for (uint i = 0; i < setupCount; i++)
        {
            const Token& t = tokens[i];
            const SemanticValue value = (t.m_name == "mem") ? SemanticValue() :
                                        parseHex(t.m_value, t.m_end);
            uint index = 0;
            const cSArray<char> name = t.m_name.getASCIIstring();
            if (t.m_name == "mem")
                parseMemory(t.m_value, t.m_end, memory, NULL);
            else if ((sscanf(name.getBuffer(), "x%u", &index) == 1) && (index < 31))
                initialX[index] = value.getWord(0);
            else if ((sscanf(name.getBuffer(), "v%u", &index) == 1) && (index < 32))
                initialV[index] = value;
            else if (t.m_name == "sp")
                initialSp = value.getWord(0);
            else if (t.m_name == "pc")
                pc = value.getWord(0);
            else if (t.m_name == "nzcv")
                initialNzcv = (uint)value.getWord(0);
            else if (t.m_name == "fpcr")
                initialFpcr = value.getWord(0);
            else if (t.m_name == "fpsr")
                initialFpsr = value.getWord(0);
            else
                ARM_ASSERT_TOKEN(false);
        }

        // Decode and lift
        SemanticBlock block(OpcodeSubsystems::DISASSEMBLER_ARM_64_LE);
        bool isLifted = true;
        for (uint i = 0; i < row.m_count; i++)
        {
            ArmOpcodePtr opcode = ArmStreamDisassembler::decode(
                    ArmInstructionSet::ARM_A64, row.m_words[i], 4, pc + 4 * i,
                    ArmFeatureSet::all());
            if (opcode.getPointer() == NULL)
            {
                ARM_SEMANTIC_FAIL(row.m_text, "the word doesn't decode");
                return;
            }
            if (!lifter.lift(asOpcode(opcode), block))
                isLifted = false;
        }
        block.setFallThroughAddress(ProcessorAddress(ProcessorAddress::PROCESSOR_64,
                                                     pc + 4 * row.m_count));

        for (uint i = 0; i < 31; i++)
            interpreter.setRegister(ARM64_REG_X0 + i, SemanticValue(initialX[i]));
        interpreter.setRegister(ARM64_REG_SP, SemanticValue(initialSp));
        interpreter.setRegister(ARM64_REG_PC, SemanticValue(pc));
        interpreter.setRegister(ARM64_REG_N, SemanticValue((initialNzcv >> 3) & 1));
        interpreter.setRegister(ARM64_REG_Z, SemanticValue((initialNzcv >> 2) & 1));
        interpreter.setRegister(ARM64_REG_C, SemanticValue((initialNzcv >> 1) & 1));
        interpreter.setRegister(ARM64_REG_V, SemanticValue(initialNzcv & 1));
        interpreter.setRegister(ARM64_REG_FPCR, SemanticValue(initialFpcr));
        interpreter.setRegister(ARM64_REG_FPSR, SemanticValue(initialFpsr));
        for (uint i = 0; i < 32; i++)
            interpreter.setRegister(ARM64_REG_Z0 + i, initialV[i]);
        const SemanticInterpreter::ExitReason reason = interpreter.run(block);

        // The expected state
        cString exitName = "fall";
        bool hasX[31], hasV[32];
        uint64 expectedX[31];
        SemanticValue expectedV[32];
        bool hasSp = false, hasNzcv = false, hasPc = false, hasFpcr = false,
             hasFpsr = false, hasTrap = false;
        uint64 expectedSp = 0, expectedPc = 0, expectedFpcr = 0, expectedFpsr = 0,
               expectedTrap = 0;
        uint expectedNzcv = 0;
        cHash<uint64, uint8> expectedMemory;
        for (uint i = 0; i < 31; i++)
            hasX[i] = false;
        for (uint i = 0; i < 32; i++)
            hasV[i] = false;
        const uint expectedCount = split(row.m_expected, tokens, 64);
        for (uint i = 0; i < expectedCount; i++)
        {
            const Token& t = tokens[i];
            uint index = 0;
            const cSArray<char> ascii = cString(t.m_name).getASCIIstring();
            if (t.m_name == "exit")
            {
                exitName = cString(cString(t.m_value).left((uint)(t.m_end - t.m_value)));
                continue;
            }
            if (t.m_name == "mem")
            {
                parseMemory(t.m_value, t.m_end, memory, &expectedMemory);
                continue;
            }
            const SemanticValue value = parseHex(t.m_value, t.m_end);
            if (sscanf(ascii.getBuffer(), "x%u", &index) == 1)
            {
                hasX[index] = true;
                expectedX[index] = value.getWord(0);
            } else if (sscanf(ascii.getBuffer(), "v%u", &index) == 1)
            {
                hasV[index] = true;
                expectedV[index] = value;
            } else if (t.m_name == "sp")
            {
                hasSp = true;
                expectedSp = value.getWord(0);
            } else if (t.m_name == "pc")
            {
                hasPc = true;
                expectedPc = value.getWord(0);
            } else if (t.m_name == "nzcv")
            {
                hasNzcv = true;
                expectedNzcv = (uint)value.getWord(0);
            } else if (t.m_name == "fpcr")
            {
                hasFpcr = true;
                expectedFpcr = value.getWord(0);
            } else if (t.m_name == "fpsr")
            {
                hasFpsr = true;
                expectedFpsr = value.getWord(0);
            } else if (t.m_name == "trapnumber")
            {
                hasTrap = true;
                expectedTrap = value.getWord(0);
            } else
            {
                ARM_ASSERT_TOKEN(false);
            }
        }

        // The exit
        cString actualExit;
        switch (reason)
        {
        case SemanticInterpreter::EXIT_FALL_THROUGH: actualExit = "fall"; break;
        case SemanticInterpreter::EXIT_BRANCH: actualExit = "branch"; break;
        case SemanticInterpreter::EXIT_MEMORY_FAULT: actualExit = "fault"; break;
        case SemanticInterpreter::EXIT_HELPER: actualExit = "helper"; break;
        case SemanticInterpreter::EXIT_UNDEFINED: actualExit = "undefined"; break;
        case SemanticInterpreter::EXIT_TRAP:
            switch (interpreter.getTrapKind())
            {
            case SemanticOperation::TRAP_SYSTEM_CALL: actualExit = "trap:svc"; break;
            case SemanticOperation::TRAP_BREAKPOINT: actualExit = "trap:brk"; break;
            case SemanticOperation::TRAP_UNDEFINED: actualExit = "trap:undef"; break;
            default: actualExit = "trap:other"; break;
            }
            break;
        default:
            actualExit = "other";
            break;
        }
        // A taken branch to the next instruction is also a fall through
        if ((exitName == "fall") && (actualExit == "branch") &&
            (interpreter.getNextAddress() == pc + 4 * row.m_count))
            actualExit = "fall";
        if (!(actualExit == exitName))
        {
            char message[256];
            snprintf(message, sizeof(message), "exit %s, expected %s",
                     actualExit.getASCIIstring().getBuffer(),
                     exitName.getASCIIstring().getBuffer());
            ARM_SEMANTIC_FAIL(row.m_text, message);
            return;
        }
        if ((exitName == "undefined") && isLifted)
            ARM_SEMANTIC_FAIL(row.m_text, "lift() returned true for an undefined instruction");
        if ((exitName != "fall") && (exitName != "branch"))
        {
            if (hasTrap && (interpreter.getTrapNumber() != expectedTrap))
                ARM_SEMANTIC_FAIL(row.m_text, "trap number");
            return;
        }
        if (hasPc || (exitName == "fall"))
        {
            const uint64 wanted = hasPc ? expectedPc : (pc + 4 * row.m_count);
            if (interpreter.getNextAddress() != wanted)
            {
                char message[256];
                snprintf(message, sizeof(message), "pc %llx, expected %llx",
                         (unsigned long long)interpreter.getNextAddress(),
                         (unsigned long long)wanted);
                ARM_SEMANTIC_FAIL(row.m_text, message);
            }
        }

        // The registers
        for (uint i = 0; i < 31; i++)
        {
            const uint64 wanted = hasX[i] ? expectedX[i] : initialX[i];
            const uint64 actual = interpreter.getRegister(ARM64_REG_X0 + i).getWord(0);
            if (actual != wanted)
            {
                char message[256];
                snprintf(message, sizeof(message), "x%u = %llx, expected %llx", i,
                         (unsigned long long)actual, (unsigned long long)wanted);
                ARM_SEMANTIC_FAIL(row.m_text, message);
            }
        }
        const uint64 wantedSp = hasSp ? expectedSp : initialSp;
        if (interpreter.getRegister(ARM64_REG_SP).getWord(0) != wantedSp)
            ARM_SEMANTIC_FAIL(row.m_text, "sp");
        uint nzcv = 0;
        if (interpreter.getRegister(ARM64_REG_N).getBits(0, 1) != 0) nzcv |= 8;
        if (interpreter.getRegister(ARM64_REG_Z).getBits(0, 1) != 0) nzcv |= 4;
        if (interpreter.getRegister(ARM64_REG_C).getBits(0, 1) != 0) nzcv |= 2;
        if (interpreter.getRegister(ARM64_REG_V).getBits(0, 1) != 0) nzcv |= 1;
        if (nzcv != (hasNzcv ? expectedNzcv : initialNzcv))
        {
            char message[256];
            snprintf(message, sizeof(message), "nzcv = %x, expected %x", nzcv,
                     hasNzcv ? expectedNzcv : initialNzcv);
            ARM_SEMANTIC_FAIL(row.m_text, message);
        }
        if (interpreter.getRegister(ARM64_REG_FPCR).getWord(0) !=
            (hasFpcr ? expectedFpcr : initialFpcr))
            ARM_SEMANTIC_FAIL(row.m_text, "fpcr");
        if (interpreter.getRegister(ARM64_REG_FPSR).getWord(0) !=
            (hasFpsr ? expectedFpsr : initialFpsr))
            ARM_SEMANTIC_FAIL(row.m_text, "fpsr");
        for (uint i = 0; i < 32; i++)
        {
            SemanticValue actual = interpreter.getRegister(ARM64_REG_Q0 + i);
            const SemanticValue& wanted = hasV[i] ? expectedV[i] : initialV[i];
            if (actual != wanted)
            {
                char message[256];
                snprintf(message, sizeof(message), "v%u", i);
                ARM_SEMANTIC_FAIL(row.m_text, message);
            }
            // The rest of z is zero (a write zeroes it)
            if ((interpreter.getRegister(ARM64_REG_Z0 + i).getWord(2) != 0) ||
                (interpreter.getRegister(ARM64_REG_Z0 + i).getWord(3) != 0))
                ARM_SEMANTIC_FAIL(row.m_text, "z above 128 bits");
        }

        // The memory: the expected bytes, and nothing else changed
        cList<uint64> keys = expectedMemory.keys();
        for (cList<uint64>::iterator i = keys.begin(); i != keys.end(); i++)
        {
            if (memory.getByte(*i) != expectedMemory[*i])
            {
                char message[256];
                snprintf(message, sizeof(message), "mem[%llx] = %02x, expected %02x",
                         (unsigned long long)*i, memory.getByte(*i), expectedMemory[*i]);
                ARM_SEMANTIC_FAIL(row.m_text, message);
            }
        }
    }

    // The writes which the row doesn't expect: a check on the rows with a mem
    // token or without (a store which writes where it should not)
    void checkNoStrayWrites()
    {
        // Covered by the register and memory comparisons of runRow(): a stray
        // write of a register or an expected-memory mismatch fails the row
    }

    void testRows()
    {
        uint rows = 0;
        for (const Arm64SemanticRow* row = gArm64SemanticRows; row->m_text != NULL; row++)
        {
            runRow(*row);
            rows++;
        }
        cout << rows << " A64 semantic rows run, " << m_failures << " failures" << endl;
        TESTS_ASSERT(m_failures == 0);
    }

    // The classification of the lifted mnemonics
    void testClassification()
    {
        ArmSemanticLifter lifter(OpcodeSubsystems::DISASSEMBLER_ARM_64_LE);
        struct {
            uint32 m_word;
            OpcodeClassification::Category m_category;
            uint32 m_properties;
        } cases[] = {
            { 0x8b020020, OpcodeClassification::CATEGORY_ARITHMETIC, 0 },
            { 0xf9400020, OpcodeClassification::CATEGORY_LOAD,
              OpcodeClassification::PROPERTY_READS_MEMORY },
            { 0xf9000020, OpcodeClassification::CATEGORY_STORE,
              OpcodeClassification::PROPERTY_WRITES_MEMORY },
            { 0x54000040, OpcodeClassification::CATEGORY_BRANCH,
              OpcodeClassification::PROPERTY_CONDITIONAL },
            { 0xd65f03c0, OpcodeClassification::CATEGORY_RETURN, 0 },
            { 0xc85f7c20, OpcodeClassification::CATEGORY_ATOMIC,
              OpcodeClassification::PROPERTY_EXCLUSIVE },
            { 0x1ac20c20, OpcodeClassification::CATEGORY_DIVIDE, 0 },
            { 0xd4000021, OpcodeClassification::CATEGORY_INTERRUPT, 0 }
        };
        for (uint i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
        {
            ArmOpcodePtr opcode = ArmStreamDisassembler::decode(
                ArmInstructionSet::ARM_A64, cases[i].m_word, 4, 0x1000,
                ArmFeatureSet::all());
            TESTS_ASSERT(opcode.getPointer() != NULL);
            const OpcodeClassification c = lifter.classify(asOpcode(opcode));
            if (c.getCategory() != cases[i].m_category)
                cout << "FAILED classification of word " << HEXDWORD(cases[i].m_word) << endl;
            TESTS_ASSERT(c.getCategory() == cases[i].m_category);
            TESTS_ASSERT(c.hasProperty(cases[i].m_properties));
        }
        // subs sets all four flags; adc reads the carry
        ArmOpcodePtr subs = ArmStreamDisassembler::decode(
            ArmInstructionSet::ARM_A64, 0xeb020020, 4, 0x1000, ArmFeatureSet::all());
        const OpcodeClassification s = lifter.classify(asOpcode(subs));
        TESTS_ASSERT(s.getFlagsWritten() ==
            (SemanticFlags::FLAG_SIGN | SemanticFlags::FLAG_ZERO |
             SemanticFlags::FLAG_CARRY | SemanticFlags::FLAG_OVERFLOW));
        TESTS_ASSERT(s.hasProperty(OpcodeClassification::PROPERTY_WRITES_FLAGS));
        // A mnemonic which isn't lifted (FEAT_MOPS cpyfp) is unclassified
        // and lifts to OP_UNDEFINED
        ArmOpcodePtr mops = ArmStreamDisassembler::decode(
            ArmInstructionSet::ARM_A64, 0x19010440, 4, 0x1000, ArmFeatureSet::all());
        TESTS_ASSERT(mops.getPointer() != NULL);
        TESTS_ASSERT(lifter.classify(asOpcode(mops)).getCategory() ==
                     OpcodeClassification::CATEGORY_UNKNOWN);
        SemanticBlock block(OpcodeSubsystems::DISASSEMBLER_ARM_64_LE);
        TESTS_ASSERT(!lifter.lift(asOpcode(mops), block));
        TESTS_ASSERT(block.getInstructions().length() == 1);
        // The factory knows the processors
        SemanticLifterPtr factory = SemanticLifterFactory::getLifter(
                                OpcodeSubsystems::DISASSEMBLER_ARM_64_LE);
        TESTS_ASSERT(factory.getPointer() != NULL);
    }

    /////////////////////////////////////////////////////////////////////
    // AArch32: hand built instructions (the A32 / T32 tables come with
    // their decoders)
    /////////////////////////////////////////////////////////////////////

    static ArmDecodedOperand reg(uint id)
    {
        ArmDecodedOperand operand;
        operand.m_kind = ArmDecodedOperand::KIND_REGISTER;
        operand.m_register = id;
        return operand;
    }

    static ArmDecodedOperand imm(int64 value)
    {
        ArmDecodedOperand operand;
        operand.m_kind = ArmDecodedOperand::KIND_IMMEDIATE;
        operand.m_immediate = value;
        return operand;
    }

    static ArmDecodedOperand target(uint64 address)
    {
        ArmDecodedOperand operand;
        operand.m_kind = ArmDecodedOperand::KIND_BRANCH_TARGET;
        operand.m_immediate = (int64)address;
        return operand;
    }

    static ArmDecodedOperand memoryOffset(uint base, int64 offset)
    {
        ArmDecodedOperand operand;
        operand.m_kind = ArmDecodedOperand::KIND_MEMORY;
        operand.m_base = base;
        operand.m_offset = offset;
        return operand;
    }

    // The state of an AArch32 run
    struct A32Run {
        A32Run() : m_exit(SemanticInterpreter::EXIT_FALL_THROUGH), m_next(0) {}
        SemanticInterpreter::ExitReason m_exit;
        uint64 m_next;
        uint64 m_r[16];
        uint64 m_t;
        uint m_nzcv;
    };

    // Lift one hand built instruction (the entry is static: the opcode keeps its
    // pointer) and run it from r0..r12 = values, sp, lr, the flags and T. The
    // instruction is at 0x1000
    A32Run runA32(bool isThumb, const char* mnemonic, uint condition,
                  const ArmDecodedOperand* operands, uint count,
                  const uint64* registers, uint nzcv, TestArmRunMemory& memory)
    {
        static ArmEncodingEntry entries[8];
        static char names[8][16];
        static uint used = 0;
        ArmEncodingEntry& entry = entries[used % 8];
        memset(&entry, 0, sizeof(entry));
        strncpy(names[used % 8], mnemonic, sizeof(names[0]) - 1);
        entry.m_mnemonic = names[used % 8];
        used++;
        ArmOpcodePtr opcode(new ArmOpcode(
                         isThumb ? ArmInstructionSet::ARM_T32 : ArmInstructionSet::ARM_A32,
                         true, ProcessorAddress(ProcessorAddress::PROCESSOR_32, 0x1000),
                         0, isThumb ? 2 : 4, &entry, condition, 0));
        for (uint i = 0; i < count; i++)
            opcode->addOperand(operands[i]);
        opcode->setMnemonic(cString(mnemonic));

        const OpcodeSubsystems::DisassemblerType type = isThumb ?
            OpcodeSubsystems::DISASSEMBLER_THUMB_LE : OpcodeSubsystems::DISASSEMBLER_ARM_32_LE;
        ArchitectureDescriptionPtr architecture(new ArmArchitecture());
        ArmSemanticLifter lifter(type, architecture);
        SemanticBlock block(type);
        TESTS_ASSERT(lifter.lift(asOpcode(opcode), block));
        block.setFallThroughAddress(ProcessorAddress(ProcessorAddress::PROCESSOR_32,
                                                     0x1000 + (isThumb ? 2 : 4)));

        SemanticInterpreter interpreter(architecture, memory);
        for (uint i = 0; i < 16; i++)
            interpreter.setRegister(ARM_REG_R0 + i, SemanticValue(registers[i]));
        interpreter.setRegister(ARM_REG_PC, SemanticValue(0x1000));
        interpreter.setRegister(ARM_REG_T, SemanticValue(isThumb ? 1 : 0));
        interpreter.setRegister(ARM_REG_N, SemanticValue((nzcv >> 3) & 1));
        interpreter.setRegister(ARM_REG_Z, SemanticValue((nzcv >> 2) & 1));
        interpreter.setRegister(ARM_REG_C, SemanticValue((nzcv >> 1) & 1));
        interpreter.setRegister(ARM_REG_V, SemanticValue(nzcv & 1));
        A32Run result;
        result.m_exit = interpreter.run(block);
        result.m_next = interpreter.getNextAddress();
        for (uint i = 0; i < 16; i++)
            result.m_r[i] = interpreter.getRegister(ARM_REG_R0 + i).getWord(0);
        result.m_t = interpreter.getRegister(ARM_REG_T).getWord(0);
        result.m_nzcv = 0;
        if (interpreter.getRegister(ARM_REG_N).getBits(0, 1) != 0) result.m_nzcv |= 8;
        if (interpreter.getRegister(ARM_REG_Z).getBits(0, 1) != 0) result.m_nzcv |= 4;
        if (interpreter.getRegister(ARM_REG_C).getBits(0, 1) != 0) result.m_nzcv |= 2;
        if (interpreter.getRegister(ARM_REG_V).getBits(0, 1) != 0) result.m_nzcv |= 1;
        return result;
    }

    void testAArch32()
    {
        TestArmRunMemory memory;
        uint64 r[16];
        for (uint i = 0; i < 16; i++)
            r[i] = 0x100 + i;
        ArmDecodedOperand ops[3];

        // mov r0, r1: a plain move, falls through
        ops[0] = reg(ARM_REG_R0); ops[1] = reg(ARM_REG_R1);
        A32Run run = runA32(false, "mov", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_exit == SemanticInterpreter::EXIT_FALL_THROUGH);
        TESTS_ASSERT(run.m_r[0] == 0x101);
        TESTS_ASSERT(run.m_next == 0x1004);

        // mov r0, pc: the pc reads as the address + 8 (A32) and + 4 (T32)
        ops[0] = reg(ARM_REG_R0); ops[1] = reg(ARM_REG_PC);
        run = runA32(false, "mov", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0x1008);
        run = runA32(true, "mov", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0x1004);
        TESTS_ASSERT(run.m_next == 0x1002);

        // add r0, pc, #4 = 0x100c
        ops[0] = reg(ARM_REG_R0); ops[1] = reg(ARM_REG_PC); ops[2] = imm(4);
        run = runA32(false, "add", ArmOpcode::CONDITION_ALWAYS, ops, 3, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0x100c);

        // The condition wraps the instruction: moveq writes only if Z is set,
        // movne only if it is clear (hi / ls are the composite ones)
        ops[0] = reg(ARM_REG_R0); ops[1] = imm(5);
        run = runA32(false, "mov", 0 /* eq */, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0x100);
        run = runA32(false, "mov", 0, ops, 2, r, 4, memory);
        TESTS_ASSERT(run.m_r[0] == 5);
        run = runA32(false, "mov", 1 /* ne */, ops, 2, r, 4, memory);
        TESTS_ASSERT(run.m_r[0] == 0x100);
        // hi: C and not Z. ls: not C or Z
        for (uint nzcv = 0; nzcv < 16; nzcv++)
        {
            const bool c = (nzcv & 2) != 0, z = (nzcv & 4) != 0;
            run = runA32(false, "mov", 8 /* hi */, ops, 2, r, nzcv, memory);
            TESTS_ASSERT((run.m_r[0] == 5) == (c && !z));
            run = runA32(false, "mov", 9 /* ls */, ops, 2, r, nzcv, memory);
            TESTS_ASSERT((run.m_r[0] == 5) == (!c || z));
        }

        // b with a condition: not taken falls through
        ops[0] = target(0x1100);
        run = runA32(false, "b", 0, ops, 1, r, 0, memory);
        TESTS_ASSERT(run.m_exit == SemanticInterpreter::EXIT_FALL_THROUGH);
        run = runA32(false, "b", 0, ops, 1, r, 4, memory);
        TESTS_ASSERT(run.m_exit == SemanticInterpreter::EXIT_BRANCH);
        TESTS_ASSERT(run.m_next == 0x1100);

        // bl: lr is the next instruction (A32), with bit 0 set in T32
        run = runA32(false, "bl", ArmOpcode::CONDITION_ALWAYS, ops, 1, r, 0, memory);
        TESTS_ASSERT(run.m_exit == SemanticInterpreter::EXIT_BRANCH);
        TESTS_ASSERT(run.m_r[14] == 0x1004);
        run = runA32(true, "bl", ArmOpcode::CONDITION_ALWAYS, ops, 1, r, 0, memory);
        TESTS_ASSERT(run.m_r[14] == 0x1003);

        // bx r1: bit 0 selects the instruction set; the address is aligned
        struct { uint64 m_target; uint64 m_next; uint64 m_t; } bx[] = {
            { 0x2001, 0x2000, 1 }, { 0x2000, 0x2000, 0 }, { 0x2002, 0x2000, 0 },
            { 0x2003, 0x2002, 1 }
        };
        ops[0] = reg(ARM_REG_R1);
        for (uint i = 0; i < 4; i++)
        {
            r[1] = bx[i].m_target;
            run = runA32(false, "bx", ArmOpcode::CONDITION_ALWAYS, ops, 1, r, 0, memory);
            TESTS_ASSERT(run.m_exit == SemanticInterpreter::EXIT_BRANCH);
            TESTS_ASSERT(run.m_next == bx[i].m_next);
            TESTS_ASSERT(run.m_t == bx[i].m_t);
        }
        // T32 bx to an even address switches to A32
        r[1] = 0x2000;
        run = runA32(true, "bx", ArmOpcode::CONDITION_ALWAYS, ops, 1, r, 0, memory);
        TESTS_ASSERT(run.m_t == 0);
        TESTS_ASSERT(run.m_next == 0x2000);

        // blx r1: the target is read before lr is written (blx lr)
        r[1] = 0x3001;
        run = runA32(false, "blx", ArmOpcode::CONDITION_ALWAYS, ops, 1, r, 0, memory);
        TESTS_ASSERT(run.m_next == 0x3000);
        TESTS_ASSERT(run.m_t == 1);
        TESTS_ASSERT(run.m_r[14] == 0x1004);
        ops[0] = reg(ARM_REG_LR);
        r[14] = 0x5001;
        run = runA32(false, "blx", ArmOpcode::CONDITION_ALWAYS, ops, 1, r, 0, memory);
        TESTS_ASSERT(run.m_next == 0x5000);
        TESTS_ASSERT(run.m_r[14] == 0x1004);
        r[14] = 0x100 + 14;

        // ldr pc, [r1]: the loaded value interworks (A32 and T32)
        for (uint i = 0; i < 4; i++)
            memory.set(0x6000 + i, (uint8)(0x6001 >> (8 * i)), false);
        r[1] = 0x6000;
        ops[0] = reg(ARM_REG_PC); ops[1] = memoryOffset(ARM_REG_R1, 0);
        run = runA32(false, "ldr", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_exit == SemanticInterpreter::EXIT_BRANCH);
        TESTS_ASSERT(run.m_next == 0x6000);
        TESTS_ASSERT(run.m_t == 1);
        run = runA32(true, "ldr", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_next == 0x6000);
        TESTS_ASSERT(run.m_t == 1);

        // The shifted register operand: add r0, r1, r2, lsl #2 / lsr #4 / asr #4 / ror #4 /
        // rrx (the carry shifts in)
        r[1] = 0x101;
        r[2] = 0x80000102;
        ArmDecodedOperand shifted;
        shifted.m_kind = ArmDecodedOperand::KIND_SHIFTED_REGISTER;
        shifted.m_register = ARM_REG_R2;
        struct { uint m_shift; uint m_amount; uint nzcv; uint32 m_value; } shifts[] = {
            { ArmDecodedOperand::SHIFT_LSL, 2, 0, 0x00000408 },
            { ArmDecodedOperand::SHIFT_LSR, 4, 0, 0x08000010 },
            { ArmDecodedOperand::SHIFT_ASR, 4, 0, 0xf8000010 },
            { ArmDecodedOperand::SHIFT_ROR, 4, 0, 0x28000010 },
            { ArmDecodedOperand::SHIFT_RRX, 1, 2, 0xc0000081 },
            { ArmDecodedOperand::SHIFT_RRX, 1, 0, 0x40000081 },
            { ArmDecodedOperand::EXTEND_UXTB, 0, 0, 0x02 },
            { ArmDecodedOperand::EXTEND_SXTH, 1, 0, 0x204 }
        };
        for (uint i = 0; i < sizeof(shifts) / sizeof(shifts[0]); i++)
        {
            shifted.m_shift = shifts[i].m_shift;
            shifted.m_shiftAmount = shifts[i].m_amount;
            ops[0] = reg(ARM_REG_R0); ops[1] = reg(ARM_REG_R1); ops[2] = shifted;
            run = runA32(false, "add", ArmOpcode::CONDITION_ALWAYS, ops, 3, r,
                         shifts[i].nzcv, memory);
            if (run.m_r[0] != (uint32)(0x101 + shifts[i].m_value))
                cout << "FAILED shift " << i << ": " << HEXDWORD((uint32)run.m_r[0]) << endl;
            TESTS_ASSERT(run.m_r[0] == (uint32)(0x101 + shifts[i].m_value));
        }

        // The memory operand: the offset, the register offset with a shift, the
        // pre index and the post index writeback
        for (uint i = 0; i < 16; i++)
            memory.set(0x7000 + i, (uint8)(0xa0 + i), false);
        r[1] = 0x7004;
        r[2] = 2;
        ops[0] = reg(ARM_REG_R0); ops[1] = memoryOffset(ARM_REG_R1, 4);
        run = runA32(false, "ldr", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0xabaaa9a8);
        TESTS_ASSERT(run.m_r[1] == 0x7004);
        ops[1] = memoryOffset(ARM_REG_R1, 4);
        ops[1].m_addressing = ArmDecodedOperand::ADDRESSING_PRE_INDEX;
        run = runA32(false, "ldr", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0xabaaa9a8);
        TESTS_ASSERT(run.m_r[1] == 0x7008);
        ops[1] = memoryOffset(ARM_REG_R1, 4);
        ops[1].m_addressing = ArmDecodedOperand::ADDRESSING_POST_INDEX;
        run = runA32(false, "ldr", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0xa7a6a5a4);
        TESTS_ASSERT(run.m_r[1] == 0x7008);
        ops[1] = memoryOffset(ARM_REG_R1, 0);
        ops[1].m_index = ARM_REG_R2;
        ops[1].m_shift = ArmDecodedOperand::SHIFT_LSL;
        ops[1].m_shiftAmount = 2;
        ops[1].m_isSubtract = true;
        r[1] = 0x700c;
        run = runA32(false, "ldr", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_r[0] == 0xa7a6a5a4);

        // mov pc, r1: the A32 data processing interworks, the T32 one doesn't
        // (the T bit stays, bit 0 is dropped)
        r[1] = 0x4001;
        ops[0] = reg(ARM_REG_PC); ops[1] = reg(ARM_REG_R1);
        run = runA32(false, "mov", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_next == 0x4000);
        TESTS_ASSERT(run.m_t == 1);
        r[1] = 0x4002;
        run = runA32(false, "mov", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_next == 0x4000);
        TESTS_ASSERT(run.m_t == 0);
        r[1] = 0x4003;
        run = runA32(true, "mov", ArmOpcode::CONDITION_ALWAYS, ops, 2, r, 0, memory);
        TESTS_ASSERT(run.m_next == 0x4002);
        TESTS_ASSERT(run.m_t == 1);
        r[1] = 0x101;
    }

    virtual void test()
    {
        testRows();
        testClassification();
        testAArch32();
        cout << "ARM semantics tests passed" << endl;
    }

    // Return the name of the module
    virtual cString getName() { return __FILE__; }

private:
    uint m_failures;
};

// Instance test object
TestObjectTestArm64Semantics g_globalTestArm64Semantics;
